#include <stdio.h>
#include <stdlib.h>

int global_initialized = 42;    // Data Segment
int global_uninitialized;       // BSS Segment (Zero-initialized by OS)

int main(void) {
    printf("=== 01: Memory Layout of a C Program ===\n");

    int local_stack_var = 10;   // Stack Frame
    int* heap_var = (int*)malloc(sizeof(int)); // Heap
    *heap_var = 100;

    printf("Address of Data Segment (global_initialized)  : %p\n", (void*)&global_initialized);
    printf("Address of BSS Segment  (global_uninitialized): %p\n", (void*)&global_uninitialized);
    printf("Address of Heap Memory  (heap_var)            : %p\n", (void*)heap_var);
    printf("Address of Stack Memory (local_stack_var)     : %p\n", (void*)&local_stack_var);

    free(heap_var);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

int main(void) {
    printf("=== 02: Primitive Types & <stdint.h> Fixed-Width Integers ===\n");

    int8_t  small_val = -128;
    uint8_t byte_val  = 255;
    int32_t fixed_32  = 1000000;
    uint64_t fixed_64 = 18446744073709551615ULL;

    printf("int8_t : %d (size: %zu byte)\n", small_val, sizeof(small_val));
    printf("uint8_t: %u (size: %zu byte)\n", byte_val, sizeof(byte_val));
    printf("int32_t: %d (size: %zu bytes)\n", fixed_32, sizeof(fixed_32));
    printf("uint64_t: %llu (size: %zu bytes)\n", (unsigned long long)fixed_64, sizeof(fixed_64));
    return 0;
}

#include <stdio.h>

int main(void) {
    printf("=== 03: Pointers, Double Pointers & Arithmetic ===\n");

    int val = 42;
    int* ptr = &val;     // Pointer
    int** dptr = &ptr;   // Double pointer (pointer to pointer)

    printf("Value direct            : %d\n", val);
    printf("Value via pointer (*ptr) : %d\n", *ptr);
    printf("Value via dptr (**dptr)  : %d\n", **dptr);

    // Pointer Arithmetic
    int arr[3] = {10, 20, 30};
    int* pArr = arr;
    printf("arr[0]: %d | *(pArr + 1): %d | *(pArr + 2): %d\n", *pArr, *(pArr + 1), *(pArr + 2));
    return 0;
}

