#include <stdio.h>
#include <stdlib.h>

int main(void) {
    printf("=== 05: Dynamic Memory (malloc, calloc, realloc, free) ===\n");

    // 1. malloc: Allocates uninitialized memory
    int* nums = (int*)malloc(3 * sizeof(int));
    if (!nums) return 1;

    nums[0] = 10; nums[1] = 20; nums[2] = 30;

    // 2. realloc: Resizes memory buffer
    int* expanded = (int*)realloc(nums, 5 * sizeof(int));
    if (!expanded) { free(nums); return 1; }
    nums = expanded;
    nums[3] = 40; nums[4] = 50;

    for (int i = 0; i < 5; ++i) printf("%d ", nums[i]);
    printf("\n");

    free(nums); // Always free to avoid memory leaks!
    nums = NULL; // Avoid dangling pointer
    return 0;
}

#include <stdio.h>

// Struct with default memory alignment padding
struct Padded {
    char c;    // 1 byte + 3 bytes padding
    int i;     // 4 bytes
    short s;   // 2 bytes + 2 bytes padding
};             // Total = 12 bytes!

// Packed struct with zero padding
#pragma pack(push, 1)
struct Packed {
    char c;    // 1 byte
    int i;     // 4 bytes
    short s;   // 2 bytes
};             // Total = 7 bytes!
#pragma pack(pop)

int main(void) {
    printf("=== 06: Structs, Alignment & Padding ===\n");
    printf("Size of Padded struct: %zu bytes\n", sizeof(struct Padded));
    printf("Size of Packed struct: %zu bytes\n", sizeof(struct Packed));
    return 0;
}

#include <stdio.h>

int add(int a, int b) { return a + b; }
int multiply(int a, int b) { return a * b; }

// Higher-order function taking a function pointer callback
void executeOp(int (*op)(int, int), int x, int y) {
    printf("Operation Result: %d\n", op(x, y));
}

int main(void) {
    printf("=== 07: Function Pointers & Callbacks ===\n");
    executeOp(add, 5, 10);
    executeOp(multiply, 5, 10);
    return 0;
}

#include <stdio.h>

void counterFunction(void) {
    static int callCount = 0; // Preserves value across function calls (in Data/BSS)
    callCount++;
    printf("Function call count: %d\n", callCount);
}

int main(void) {
    printf("=== 08: Storage Classes (auto, static, extern) ===\n");
    counterFunction();
    counterFunction();
    counterFunction();
    return 0;
}

#include <stdio.h>

// restrict: Tells compiler pointers do not alias, enabling vectorization
void addArrays(int* restrict a, const int* restrict b, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        a[i] += b[i];
    }
}

int main(void) {
    printf("=== 09: Type Qualifiers: const, volatile & restrict ===\n");
    int arr1[3] = {1, 2, 3};
    int arr2[3] = {10, 20, 30};
    addArrays(arr1, arr2, 3);
    printf("Result: %d %d %d\n", arr1[0], arr1[1], arr1[2]);
    return 0;
}

#include <stdio.h>

// Safe macro with parenthesis
#define SQUARE(x) ((x) * (x))

// Stringification (#) and Token Pasting (##)
#define PRINT_VAR(var) printf(#var " = %d\n", var)
#define CONCAT(a, b) a##b

int main(void) {
    printf("=== 10: Preprocessor Macros & Metaprogramming ===\n");
    int num = 5;
    PRINT_VAR(num);
    printf("Square(num + 1) = %d\n", SQUARE(num + 1)); // ((5+1) * (5+1)) = 36
    return 0;
}

#include <stdio.h>

#define SET_BIT(reg, bit)    ((reg) |= (1U << (bit)))
#define CLEAR_BIT(reg, bit)  ((reg) &= ~(1U << (bit)))
#define TOGGLE_BIT(reg, bit) ((reg) ^= (1U << (bit)))
#define CHECK_BIT(reg, bit)  (((reg) >> (bit)) & 1U)

int main(void) {
    printf("=== 11: Bit Manipulation & Bitwise Operators ===\n");
    unsigned char reg = 0;
    SET_BIT(reg, 3); // Set 3rd bit
    printf("Register value after SET_BIT(3): %u | Check bit 3: %u\n", reg, CHECK_BIT(reg, 3));

    // Endianness Check
    unsigned int test = 1;
    char* byte = (char*)&test;
    if (*byte == 1) {
        printf("Host Architecture is Little-Endian\n");
    } else {
        printf("Host Architecture is Big-Endian\n");
    }
    return 0;
}

